                    .add(new FileOperation(SNAPSHOT, "InputFile.newStream"))
                    .add(new FileOperation(MANIFEST, "InputFile.newStream")) // fewer than without filter
                    .build());

    assertUpdate("DROP TABLE test_varchar_as_date_predicate");
}

