    if (response.startsWith(server1.getJvmRoute())) {
        modClusterClient.updateLoad(server1.getJvmRoute(), -1);
    } else {
        modClusterClient.updateLoad(server2.getJvmRoute(), -1);
    }

    checkGet("/session", StatusCodes.OK);
}

