    assertResponseCode(client, getInternalLocation(baseUri), SC_FORBIDDEN, "unknown", "something");
    assertResponseCode(client, getInternalLocation(baseUri), SC_FORBIDDEN, TEST_USER_LOGIN, TEST_PASSWORD);
}

