public void testWrongGenericOnGlobal(RUN_TYPE runType) {
    // DROOLS-7155
    String def =
            "package org.drools.reproducer\n" +
            "global java.util.List<Integer> globalList;\n" +
            "rule R when\n" +
            "then\n" +
            "    globalList.add(\"test\");\n" +
            "end\n";

