    assertEquals(3, res10.longValue());
    assertEquals(1, res11.longValue());
    assertEquals(1, res12.longValue());
    assertEquals("3", res13);
    assertEquals("[1, 1]", res14.toString());
    // REMOVE_END
  }
}

