  assertThat(bitfieldResult, contains(7L, 7L));

  List<Long> bitfieldRoResult = exec(commandObjects.bitfieldReadonly(key,
      "GET".getBytes(), "i4".getBytes(), "100".getBytes()));
  assertThat(bitfieldRoResult, contains(3L));
}

