    assertThat(assertions.function("round", "TINYINT '-128'", "-2"))
            .isEqualTo((byte) -100);

    assertThat(assertions.function("round", "TINYINT '-128'", "-3"))
            .isEqualTo((byte) 0);

    assertThat(assertions.function("round", "SMALLINT '99'", "-1"))
