    // ROUND short DECIMAL -> short DECIMAL
    assertThat(assertions.function("round", "DECIMAL '0'"))
            .isEqualTo(decimal("0", createDecimalType(1)));

    assertThat(assertions.function("round", "DECIMAL '0.1'"))
            .isEqualTo(decimal("0", createDecimalType(1)));

    assertThat(assertions.function("round", "DECIMAL '-0.1'"))
