code_method:
public void testUserTransactions(String locking) throws Exception {
	setUpLocking(locking);
    String str = "";
    str += "package org.kie.test\n";
    str += "global java.util.List list\n";
    str += "rule rule1\n";
    str += "when\n";
    str += "  $i : Integer(intValue > 0)\n";
    str += "then\n";
    str += "  list.add( $i );\n";
    str += "end\n";
    str += "\n";

    KieServices ks = KieServices.Factory.get();

    KieFileSystem kfs = ks.newKieFileSystem().write( "src/main/resources/r1.drl", str );
    ks.newKieBuilder( kfs ).buildAll();

    KieBase kbase = ks.newKieContainer(ks.getRepository().getDefaultReleaseId()).getKieBase();

    UserTransaction ut = (UserTransaction) new InitialContext().lookup( "java:comp/UserTransaction" );
    ut.begin();
    KieSession ksession = ks.getStoreServices().newKieSession( kbase, null, env );
    ut.commit();

    List<?> list = new ArrayList<Object>();

    // insert and commit
    ut = (UserTransaction) new InitialContext().lookup( "java:comp/UserTransaction" );
    ut.begin();
    ksession.setGlobal( "list",
                        list );
    ksession.insert( 1 );
    ksession.insert( 2 );
    ksession.fireAllRules();
    ut.commit();

    // insert and rollback
    ut = (UserTransaction) new InitialContext().lookup( "java:comp/UserTransaction" );
    ut.begin();
    ksession.insert( 3 );
    ut.rollback();

    // check we rolled back the state changes from the 3rd insert
    ut = (UserTransaction) new InitialContext().lookup( "java:comp/UserTransaction" );
    ut.begin();
    ksession.fireAllRules();
    ut.commit();
    assertThat(list.size()).isEqualTo(2);

    // insert and commit
    ut = (UserTransaction) new InitialContext().lookup( "java:comp/UserTransaction" );
    ut.begin();
    ksession.insert( 3 );
    ksession.insert( 4 );
    ut.commit();

    // rollback again, this is testing that we can do consecutive rollbacks and commits without issue
    ut = (UserTransaction) new InitialContext().lookup( "java:comp/UserTransaction" );
    ut.begin();
    ksession.insert( 5 );
    ksession.insert( 6 );
    ut.rollback();

    ksession.fireAllRules();

    assertThat(list.size()).isEqualTo(4);

    // now load the ksession
    ksession = ks.getStoreServices().loadKieSession( ksession.getIdentifier(), kbase, null, env );

    ut = (UserTransaction) new InitialContext().lookup( "java:comp/UserTransaction" );
    ut.begin();
    ksession.insert( 7 );
    ksession.insert( 8 );
    ut.commit();

    ksession.fireAllRules();

    assertThat(list.size()).isEqualTo(6);
}

