    // count(bigint) FILTER (WHERE ...)
    testImplementAggregation(
            new AggregateFunction("count", BIGINT, List.of(bigintVariable), List.of(), false, filter),
            Map.of(bigintVariable.getName(), BIGINT_COLUMN),
            Optional.empty());
}

