            """))
            .matches("VALUES (BIGINT '-3147483647')")
            .isNotFullyPushedDown(AggregationNode.class);
    assertThat(query(
            """
            SELECT bool_col, MIN(long_col) FROM
            (SELECT bool_col, long_col FROM alltypes GROUP BY bool_col, long_col)
