code_method:
public void testLiteral()
{
    assertThat(assertions.expression("DATE '2001-1-22'"))
            .hasType(DATE)
            .isEqualTo(toDate(new DateTime(2001, 1, 22, 0, 0, UTC)));

    assertThat(assertions.expression("DATE '2013-02-02'"))
            .hasType(DATE)
            .isEqualTo(toDate(new DateTime(2013, 2, 2, 0, 0, 0, 0, UTC)));

    // one digit for month or day
    assertThat(assertions.expression("DATE '2013-2-02'"))
            .hasType(DATE)
            .isEqualTo(toDate(new DateTime(2013, 2, 2, 0, 0, 0, 0, UTC)));

    assertThat(assertions.expression("DATE '2013-02-2'"))
            .hasType(DATE)
            .isEqualTo(toDate(new DateTime(2013, 2, 2, 0, 0, 0, 0, UTC)));

    // three digit for month or day
    assertTrinoExceptionThrownBy(assertions.expression("DATE '2013-02-002'")::evaluate)
            .hasErrorCode(INVALID_LITERAL)
            .hasMessage("line 1:12: '2013-02-002' is not a valid DATE literal");

    assertTrinoExceptionThrownBy(assertions.expression("DATE '2013-002-02'")::evaluate)
            .hasErrorCode(INVALID_LITERAL)
            .hasMessage("line 1:12: '2013-002-02' is not a valid DATE literal");

    // zero-padded year
    assertThat(assertions.expression("DATE '02013-02-02'"))
            .hasType(DATE)
            .isEqualTo(toDate(new DateTime(2013, 2, 2, 0, 0, 0, 0, UTC)));

    assertThat(assertions.expression("DATE '0013-02-02'"))
            .hasType(DATE)
            .isEqualTo(toDate(new DateTime(13, 2, 2, 0, 0, 0, 0, UTC)));

    // invalid date
    assertTrinoExceptionThrownBy(assertions.expression("DATE '2013-02-29'")::evaluate)
            .hasErrorCode(INVALID_LITERAL)
            .hasMessage("line 1:12: '2013-02-29' is not a valid DATE literal");

    // surrounding whitespace
    assertThat(assertions.expression("DATE '  2013-02-02  '"))
            .hasType(DATE)
            .isEqualTo(toDate(new DateTime(2013, 2, 2, 0, 0, 0, 0, UTC)));

    assertThat(assertions.expression("DATE ' \t\n\u000B\f\r\u001C\u001D\u001E\u001F 2013-02-02 \t\n\u000B\f\n\u001C\u001D\u001E\u001F '"))
            .hasType(DATE)
            .isEqualTo(toDate(new DateTime(2013, 2, 2, 0, 0, 0, 0, UTC)));

    // intra whitespace
    assertTrinoExceptionThrownBy(assertions.expression("DATE '2013 -02-02'")::evaluate)
            .hasErrorCode(INVALID_LITERAL)
            .hasMessage("line 1:12: '2013 -02-02' is not a valid DATE literal");

    assertTrinoExceptionThrownBy(assertions.expression("DATE '2013- 2-02'")::evaluate)
            .hasErrorCode(INVALID_LITERAL)
            .hasMessage("line 1:12: '2013- 2-02' is not a valid DATE literal");

    // large year
    assertTrinoExceptionThrownBy(assertions.expression("DATE '5881580-07-12'")::evaluate)
            .hasErrorCode(INVALID_LITERAL)
            .hasMessage("line 1:12: '5881580-07-12' is not a valid DATE literal");

    assertTrinoExceptionThrownBy(assertions.expression("DATE '392251590-07-12'")::evaluate)
            .hasErrorCode(INVALID_LITERAL)
            .hasMessage("line 1:12: '392251590-07-12' is not a valid DATE literal");

    // signed
    assertThat(assertions.expression("DATE '+2013-02-02'"))
            .hasType(DATE)
            .isEqualTo(toDate(new DateTime(2013, 2, 2, 0, 0, 0, 0, UTC)));

    assertThat(assertions.expression("DATE '-2013-02-02'"))
            .hasType(DATE)
            .isEqualTo(toDate(new DateTime(-2013, 2, 2, 0, 0, 0, 0, UTC)));

    // signed with whitespace
    assertThat(assertions.expression("DATE ' +2013-02-02'"))
            .hasType(DATE)
            .isEqualTo(toDate(new DateTime(2013, 2, 2, 0, 0, 0, 0, UTC)));

    assertTrinoExceptionThrownBy(assertions.expression("DATE '+ 2013-02-02'")::evaluate)
            .hasErrorCode(INVALID_LITERAL)
            .hasMessage("line 1:12: '+ 2013-02-02' is not a valid DATE literal");

    assertTrinoExceptionThrownBy(assertions.expression("DATE ' + 2013-02-02'")::evaluate)
            .hasErrorCode(INVALID_LITERAL)
            .hasMessage("line 1:12: ' + 2013-02-02' is not a valid DATE literal");

    assertThat(assertions.expression("DATE ' -2013-02-02'"))
            .hasType(DATE)
            .isEqualTo(toDate(new DateTime(-2013, 2, 2, 0, 0, 0, 0, UTC)));

    assertTrinoExceptionThrownBy(assertions.expression("DATE '- 2013-02-02'")::evaluate)
            .hasErrorCode(INVALID_LITERAL)
            .hasMessage("line 1:12: '- 2013-02-02' is not a valid DATE literal");

    assertTrinoExceptionThrownBy(assertions.expression("DATE ' - 2013-02-02'")::evaluate)
            .hasErrorCode(INVALID_LITERAL)
            .hasMessage("line 1:12: ' - 2013-02-02' is not a valid DATE literal");
}

public void testJsonQuery()
{
    assertThat(assertions.query(
            "SELECT json_query('" + INPUT + "', 'lax $')"))
            .matches("VALUES VARCHAR '[\"a\",\"b\",\"c\"]'");

    assertThat(assertions.query(
            "SELECT json_query('" + INPUT + "', 'strict $')"))
            .matches("VALUES VARCHAR '[\"a\",\"b\",\"c\"]'");

    // structural error not suppressed by the path engine in strict mode, and handled accordingly to the ON ERROR clause

    // default error behavior is NULL ON ERROR
    assertThat(assertions.query(
            "SELECT json_query('" + INPUT + "', 'strict $[100]')"))
            .matches("VALUES cast(null AS varchar)");

    assertThat(assertions.query(
            "SELECT json_query('" + INPUT + "', 'strict $[100]' NULL ON ERROR)"))
            .matches("VALUES cast(null AS varchar)");

    assertThat(assertions.query(
            "SELECT json_query('" + INPUT + "', 'strict $[100]' EMPTY ARRAY ON ERROR)"))
            .matches("VALUES VARCHAR '[]'");

    assertThat(assertions.query(
            "SELECT json_query('" + INPUT + "', 'strict $[100]' EMPTY OBJECT ON ERROR)"))
            .matches("VALUES VARCHAR '{}'");

    assertThat(assertions.query(
            "SELECT json_query('" + INPUT + "', 'strict $[100]' ERROR ON ERROR)"))
            .failure()
            .hasErrorCode(PATH_EVALUATION_ERROR)
            .hasMessage("path evaluation failed: structural error: invalid array subscript: [100, 100] for array of size 3");

    // structural error suppressed by the path engine in lax mode. empty sequence is returned, so ON EMPTY behavior is applied

    // default empty behavior is NULL ON EMPTY
    assertThat(assertions.query(
            "SELECT json_query('" + INPUT + "', 'lax $[100]')"))
            .matches("VALUES cast(null AS varchar)");

    assertThat(assertions.query(
            "SELECT json_query('" + INPUT + "', 'lax $[100]' NULL ON EMPTY)"))
            .matches("VALUES cast(null AS varchar)");

    assertThat(assertions.query(
            "SELECT json_query('" + INPUT + "', 'lax $[100]' EMPTY ARRAY ON EMPTY)"))
            .matches("VALUES VARCHAR '[]'");

    assertThat(assertions.query(
            "SELECT json_query('" + INPUT + "', 'lax $[100]' EMPTY OBJECT ON EMPTY)"))
            .matches("VALUES VARCHAR '{}'");

    assertThat(assertions.query(
            "SELECT json_query('" + INPUT + "', 'lax $[100]' ERROR ON EMPTY)"))
            .failure()
            .hasErrorCode(JSON_OUTPUT_CONVERSION_ERROR)
            .hasMessage("conversion from JSON failed: JSON path found no items");

    // path returns multiple items (no array wrapper specified). this case is handled accordingly to the ON ERROR clause

    // default error behavior is NULL ON ERROR
    assertThat(assertions.query(
            "SELECT json_query('" + INPUT + "', 'lax $[0 to 2]')"))
            .matches("VALUES cast(null AS varchar)");

    assertThat(assertions.query(
            "SELECT json_query('" + INPUT + "', 'lax $[0 to 2]' NULL ON ERROR)"))
            .matches("VALUES cast(null AS varchar)");

    assertThat(assertions.query(
            "SELECT json_query('" + INPUT + "', 'lax $[0 to 2]' EMPTY ARRAY ON ERROR)"))
            .matches("VALUES VARCHAR '[]'");

    assertThat(assertions.query(
            "SELECT json_query('" + INPUT + "', 'lax $[0 to 2]' EMPTY OBJECT ON ERROR)"))
            .matches("VALUES VARCHAR '{}'");

    assertThat(assertions.query(
            "SELECT json_query('" + INPUT + "', 'lax $[0 to 2]' ERROR ON ERROR)"))
            .failure()
            .hasErrorCode(JSON_OUTPUT_CONVERSION_ERROR)
            .hasMessage("conversion from JSON failed: JSON path found multiple items");
}

