  assertEquals(1450152000000L, DateTime.previousInterval(DST_TS, 
      120, Calendar.MINUTE).getTimeInMillis());
  assertEquals(1431698400000L, DateTime.previousInterval(NON_DST_TS, 
      120, Calendar.MINUTE).getTimeInMillis());
}

