public void shouldPutRepeatTimestamps() {
    putToStore("k", "to_be_replaced", SEGMENT_INTERVAL + 20, PUT_RETURN_CODE_VALID_TO_UNDEFINED);
    putToStore("k", null, SEGMENT_INTERVAL - 10, SEGMENT_INTERVAL + 20);
