@Test
public void testError() {
    FutureRecordMetadata future = new FutureRecordMetadata(asyncRequest(baseOffset, new CorruptRecordException(), 50L),
            relOffset, RecordBatch.NO_TIMESTAMP, 0, 0, Time.SYSTEM);
