    assertThat(hammer.get(), notNullValue());
    assertThat(hammer.get(), sameInstance(hammer.get()));
    assertThat(hammer.get(), instanceOf(BigHammer.class));

    List<String> toolTypes = allTools.stream()
            .map(Object::getClass)
            .map(Class::getSimpleName)
