public void testChangesFromValueNodeToMissing() throws InterruptedException {
    // config source
    TestingConfigSource configSource = TestingConfigSource.builder()
            .testingPollingStrategy()
            .optional()
            .objectNode(
                    ObjectNode.builder()
                            .addValue("key1", "string value")
                            .build())
            .build();

    // config
